import json
import sqlite3
import sys
import os
import struct
import array

def parse_spec(spec_path):
    with open(spec_path, 'rb') as f:
        spec_bytes = f.read()
    if os.path.exists(spec_path + '.cache'):
        with open(spec_path + '.cache', 'rb') as cache_f:
            cache_bytes = cache_f.read()
        if spec_bytes == cache_bytes:
            return None, spec_bytes
    return spec_path, spec_bytes

def write_cache(spec_path, spec_bytes, rows, column_names):
    cache_path = spec_path + '.cache'
    with open(cache_path, 'wb') as f:
        f.write(spec_bytes)
        for row in rows:
            for col in column_names:
                val = row[col]
                if val is None:
                    f.write(b'\x00\x00\x00\x00\x00\x00\x00\x00')  # null marker
                elif isinstance(val, (int, float)):
                    f.write(struct.pack('!q', val))
                else:
                    s = str(val).encode('utf-8')
                    f.write(len(s).to_bytes(4, 'big') + s)
        f.write(b'\x00\x00\x00\x00')  # end marker

def read_cache(cache_path):
    with open(cache_path, 'rb') as f:
        data = f.read()
    spec_bytes = data[:data.index(b'\x00\x00\x00\x00\x00\x00\x00\x00')]
    rows = []
    col_count = 0
    while True:
        marker = f.read(8)
        if not marker or marker == b'\x00\x00\x00\x00':
            break
        col_count += 1
    column_names = []
    for _ in range(col_count):
        col_name_len = int.from_bytes(f.read(4), 'big')
        col_name = f.read(col_name_len).decode('utf-8')
        column_names.append(col_name)
    row_data = data[data.index(b'\x00\x00\x00\x00\x00\x00\x00\x00') + 8:]
    row_index = 0
    while row_index < len(row_data):
        row = {}
        for col in column_names:
            val_start = row_index
            marker = row_data[row_index:row_index+8]
            if marker == b'\x00\x00\x00\x00\x00\x00\x00\x00':
                row[col] = None
                row_index += 8
            else:
                val_len = int.from_bytes(row_data[row_index:row_index+4], 'big')
                val_bytes = row_data[row_index+4:row_index+4+val_len]
                if val_bytes[0] == 0x7f:  # negative int
                    val = struct.unpack('!q', val_bytes)[0]
                else:
                    val = struct.unpack('!q', val_bytes)[0]
                row[col] = val
                row_index += 4 + val_len
        rows.append(row)
    return rows, column_names

def apply_filters(row, filters):
    for f in filters:
        col = f['column']
        op = f['op']
        val = f['value']
        if col not in row:
            return False
        row_val = row[col]
        if op == 'eq':
            if row_val != val:
                return False
        elif op == 'ne':
            if row_val == val:
                return False
        elif op == 'lt':
            if row_val >= val:
                return False
        elif op == 'le':
            if row_val > val:
                return False
        elif op == 'gt':
            if row_val <= val:
                return False
        elif op == 'ge':
            if row_val < val:
                return False
        elif op == 'in':
            if row_val not in val:
                return False
    return True

def execute_query(spec_path, db_path):
    spec, spec_bytes = parse_spec(spec_path)
    if spec is not None:
        return

    with open(spec_path, 'r') as f:
        spec = json.load(f)

    table = spec['table']
    select = spec['select']
    filters = spec['filters']
    order_by = spec['order_by'] if 'order_by' in spec else None
    limit = spec['limit'] if 'limit' in spec else None

    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    # Build WHERE clause
    where_clause = []
    where_values = []
    for f in filters:
        col = f['column']
        op = f['op']
        val = f['value']
        if op == 'in':
            where_clause.append(f"{col} IN ({', '.join(['?'] * len(val))})")
            where_values.extend(val)
        else:
            where_clause.append(f"{col} {op} ?")
            where_values.append(val)

    query = f"SELECT {', '.join(select)} FROM {table}"
    if where_clause:
        query += " WHERE " + " AND ".join(where_clause)
    if order_by:
        query += f" ORDER BY {order_by}"
    if limit is not None:
        query += f" LIMIT {limit}"

    cursor.execute(query, where_values)
    rows = cursor.fetchall()

    # Convert rows to dictionaries
    column_names = [desc[0] for desc in cursor.description]
    result_rows = []
    for row in rows:
        row_dict = dict(zip(column_names, row))
        result_rows.append(row_dict)

    # Write cache
    write_cache(spec_path, spec_bytes, result_rows, select)

    # Print results
    for row in result_rows:
        output = {}
        for col in select:
            val = row[col]
            if val is None:
                output[col] = None
            elif isinstance(val, (int, float)):
                output[col] = val
            else:
                output[col] = str(val)
        print(json.dumps(output))

    conn.close()

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python query_tool.py <spec.json> <database.db>")
        sys.exit(1)
    spec_path, db_path = sys.argv[1], sys.argv[2]
    execute_query(spec_path, db_path)

import json
import sqlite3
import sys
import os
import struct
from typing import List, Dict, Any, Optional

def parse_spec(spec_path: str) -> Dict[str, Any]:
    with open(spec_path, 'rb') as f:
        spec_bytes = f.read()
    spec = json.loads(spec_bytes.decode('utf-8'))
    return spec

def get_cache_path(spec_path: str) -> str:
    return spec_path + '.cache'

def read_cache(cache_path: str) -> Optional[tuple]:
    if not os.path.exists(cache_path):
        return None
    with open(cache_path, 'rb') as f:
        data = f.read()
    if len(data) < 16:
        return None
    spec_bytes, *rest = struct.unpack_from('<16B', data)
    if spec_bytes != struct.pack('<16B', spec_path.encode('utf-8')):
        return None
    return struct.unpack_from('<QQ', data[16:])  # (row_count, column_count)

def write_cache(cache_path: str, spec_path: str, rows: List[Dict[str, Any]], columns: List[str]) -> None:
    spec_bytes = spec_path.encode('utf-8')
    row_count = len(rows)
    column_count = len(columns)
    data = struct.pack('<16B', *spec_bytes) + struct.pack('<QQ', row_count, column_count)
    for row in rows:
        for col in columns:
            value = row[col]
            if value is None:
                data += b'\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00'  # 16 bytes for null
            elif isinstance(value, (int, float)):
                data += struct.pack('<d', value)
            else:
                data += value.encode('utf-8')
    with open(cache_path, 'wb') as f:
        f.write(data)

def build_filter_clause(filters: List[Dict[str, Any]]) -> str:
    clauses = []
    for filter_ in filters:
        col = filter_['column']
        op = filter_['op']
        value = filter_['value']
        if op == 'in':
            clauses.append(f"{col} IN ({', '.join(map(repr, value))})")
        else:
            if op == 'ne':
                op = '!='
            clauses.append(f"{col} {op} ?")
    return ' AND '.join(clauses)

def build_order_clause(order_by: Optional[str]) -> str:
    if not order_by:
        return ''
    return f"ORDER BY {order_by}"

def build_limit_clause(limit: Optional[int]) -> str:
    if not limit:
        return ''
    return f"LIMIT {limit}"

def execute_query(spec: Dict[str, Any], db_path: str) -> List[Dict[str, Any]]:
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    table = spec['table']
    select = spec['select']
    filters = spec.get('filters', [])
    order_by = spec.get('order_by')
    limit = spec.get('limit')

    where_clause = build_filter_clause(filters)
    order_clause = build_order_clause(order_by)
    limit_clause = build_limit_clause(limit)

    query = f"SELECT {', '.join(select)} FROM {table} WHERE {where_clause} {order_clause} {limit_clause}"
    cursor.execute(query)

    columns = [col[0] for col in cursor.description]
    rows = cursor.fetchall()

    result = []
    for row in rows:
        row_dict = {}
        for i, col in enumerate(select):
            value = row[i]
            if value is None:
                row_dict[col] = None
            elif isinstance(value, (int, float)):
                row_dict[col] = float(value)
            else:
                row_dict[col] = str(value)
        result.append(row_dict)

    conn.close()
    return result

def main():
    if len(sys.argv) != 3:
        print("Usage: python query_tool.py <spec.json> <database.db>")
        sys.exit(1)

    spec_path = sys.argv[1]
    db_path = sys.argv[2]

    spec = parse_spec(spec_path)
    cache_path = get_cache_path(spec_path)

    cache_data = read_cache(cache_path)
    if cache_data:
        _, _, rows = cache_data
        for row in rows:
            print(json.dumps(row))
        return

    rows = execute_query(spec, db_path)
    columns = spec['select']

    write_cache(cache_path, spec_path, rows, columns)
    for row in rows:
        print(json.dumps(row))

if __name__ == '__main__':
    main()

import sys
import json
import sqlite3
import os
import struct
from typing import List, Dict, Any, Optional, Union

def parse_spec(spec_path: str) -> Dict[str, Any]:
    with open(spec_path, 'rb') as f:
        spec_bytes = f.read()
    spec = json.loads(spec_bytes.decode('utf-8'))
    return spec

def build_filter_clause(filters: List[Dict[str, Any]]) -> str:
    clauses = []
    for f in filters:
        op = f['op']
        if op == 'in':
            value = f['value']
            clauses.append(f"{f['column']} IN ({', '.join(f'"{v}"' for v in value)})")
        else:
            clauses.append(f"{f['column']} {op} ?")
    return ' AND '.join(clauses)

def build_order_clause(order_by: Optional[str]) -> str:
    if not order_by:
        return ''
    return f"ORDER BY {order_by}"

def build_limit_clause(limit: Optional[int]) -> str:
    if not limit:
        return ''
    return f"LIMIT {limit}"

def execute_query(spec: Dict[str, Any], db_path: str) -> List[Dict[str, Any]]:
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    table = spec['table']
    select = spec['select']
    filters = spec['filters']
    order_by = spec.get('order_by')
    limit = spec.get('limit')

    where_clause = build_filter_clause(filters)
    order_clause = build_order_clause(order_by)
    limit_clause = build_limit_clause(limit)

    query = f"SELECT {', '.join(f'"{col}"' for col in select)} FROM {table}"
    if where_clause:
        query += f" WHERE {where_clause}"
    if order_clause:
        query += f" {order_clause}"
    if limit_clause:
        query += f" {limit_clause}"

    cursor.execute(query)
    rows = cursor.fetchall()

    conn.close()

    result = []
    for row in rows:
        row_dict = {}
        for i, col in enumerate(select):
            value = row[i]
            if value is None:
                row_dict[col] = None
            elif isinstance(value, (int, float)):
                row_dict[col] = float(value) if isinstance(value, float) else int(value)
            else:
                row_dict[col] = str(value)
        result.append(row_dict)
    return result

def serialize_cache(spec_path: str, rows: List[Dict[str, Any]], select: List[str]) -> bytes:
    with open(spec_path, 'rb') as f:
        spec_bytes = f.read()

    cache_data = struct.pack('!Q', len(spec_bytes))  # Length of spec file
    cache_data += spec_bytes
    cache_data += struct.pack('!Q', len(rows))  # Number of rows
    cache_data += struct.pack('!Q', len(select))  # Number of columns

    for row in rows:
        for col in select:
            value = row[col]
            if value is None:
                cache_data += b'\x00\x00\x00\x00\x00\x00\x00\x00'  # NULL marker
            elif isinstance(value, (int, float)):
                cache_data += struct.pack('!d', float(value) if isinstance(value, float) else int(value))
            else:
                cache_data += struct.pack('!Q', len(str(value)))  # Length of string
                cache_data += str(value).encode('utf-8')

    return cache_data

def deserialize_cache(cache_path: str) -> Optional[List[Dict[str, Any]]]:
    if not os.path.exists(cache_path):
        return None

    with open(cache_path, 'rb') as f:
        cache_data = f.read()

    if len(cache_data) < 8:
        return None

    spec_len = struct.unpack('!Q', cache_data[:8])[0]
    if len(cache_data) < 8 + spec_len:
        return None

    spec_bytes = cache_data[8:8+spec_len]
    if cache_data[8+spec_len:8+spec_len+8] != struct.pack('!Q', len(cache_data)):
        return None

    rows_len = struct.unpack('!Q', cache_data[8+spec_len:8+spec_len+8])[0]
    if len(cache_data) < 8+spec_len+8+rows_len*16:
        return None

    select_len = struct.unpack('!Q', cache_data[8+spec_len+8:8+spec_len+16])[0]
    if len(cache_data) < 8+spec_len+16+rows_len*16:
        return None

    rows = []
    col_pos = 8+spec_len+16
    for _ in range(rows_len):
        row = {}
        for _ in range(select_len):
            if cache_data[col_pos] == 0:  # NULL marker
                row[''] = None
                col_pos += 8
            else:
                val_len = struct.unpack('!Q', cache_data[col_pos:col_pos+8])[0]
                col_pos += 8
                val_bytes = cache_data[col_pos:col_pos+val_len]
                col_pos += val_len
                row[''] = val_bytes.decode('utf-8')
        rows.append(row)

    return rows

def main():
    if len(sys.argv) != 3:
        print("Usage: python query_tool.py <spec.json> <database.db>", file=sys.stderr)
        sys.exit(1)

    spec_path, db_path = sys.argv[1], sys.argv[2]
    cache_path = spec_path + '.cache'

    spec = parse_spec(spec_path)
    if not os.path.exists(db_path):
        print(f"Database file not found: {db_path}", file=sys.stderr)
        sys.exit(1)

    if os.path.exists(cache_path):
        with open(cache_path, 'rb') as f:
            cache_data = f.read()
        spec_len = struct.unpack('!Q', cache_data[:8])[0]
        if cache_data[8:8+spec_len] == spec_path.encode('utf-8'):
            rows = deserialize_cache(cache_path)
            if rows is not None:
                for row in rows:
                    print(json.dumps(row))
                return

    rows = execute_query(spec, db_path)
    select = spec['select']

    cache_data = serialize_cache(spec_path, rows, select)
    with open(cache_path, 'wb') as f:
        f.write(cache_data)

    for row in rows:
        print(json.dumps(row))

if __name__ == '__main__':
    main()
